def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,d):
 p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert not (ROOT/'generation.json').exists(),'Do not overwrite production history'
