COMMON=('Use case: stylized-concept\nAsset type: ONE southeast neutral character concept, not an animation sheet. '
 'Create one isolated complete character, true transparent RGBA background, request 1024x1536 portrait. '
 'Camera: same true southeast front-right three-quarter as the pixel reference, facing screen DOWN-RIGHT. '
 'Style: compact adult pixel-chibi game art with the same small face, head/torso/limb proportions and deliberate stepped pixel clusters as references. '
 'Not smooth anime illustration or realistic painting. Readable at nominal size, few clear material/color masses, not excessive microtexture. '
 'One standing or naturally hovering neutral pose; at least 100 pixels transparent margin all sides, entire crown/hair/hands and support visible. '
 'No background, floor, cast shadow, props outside body, text, labels, captions, grid, watermark, duplicate figure, aura or skill FX. '
 'Wearable wardrobe accessories may be attached; all detached gear and external FX will be separate. '
 'Input references support only their stated roles. Never copy Wang face/hair/clothes into another identity. Never mirror or patch pixels.\n')
records=[];basis=[]
for slug,name,group,act,height,subject,inputs in JOBS:
 refs=[]
 for n,(src,role,zoom) in enumerate(inputs,1):
  source=WORK/src;target=ROOT/f'inputs/{slug}/{n}.png';target.parent.mkdir(parents=True,exist_ok=True)
  if zoom==1:shutil.copyfile(source,target)
  else:
   im=Image.open(source);im.resize((im.width*zoom,im.height*zoom),Image.Resampling.NEAREST).save(target)
  refs.append({'file':target.relative_to(ROOT).as_posix(),'sha256':sha(target),'original':src,'originalSha256':sha(source),'role':role,'index':n,'nearestIntegerEnlargement':zoom})
  basis.append({'file':src,'sha256':sha(source)})
 prompt=COMMON+'Primary request: '+subject+'\nNominal body/reference extent: '+str(height)+'px. Source character about900–1100px high; the source is uniformly reduced once after measuring support.\nInput roles:\n'+'\n'.join(f"Image{x['index']}: {x['role']}" for x in refs)+'\n'
 pp=ROOT/f'prompts/{slug}-r1.txt';pp.parent.mkdir(parents=True,exist_ok=True);pp.write_text(prompt,encoding='utf-8')
 records.append({'id':slug,'name':name,'group':group,'act':act,'bodyNominalPx':height,'direction':'southeast','actionsProduced':[], 'prompt':pp.relative_to(ROOT).as_posix(),'promptSha256':sha(pp),'inputs':refs,'raw':f'sources/{slug}-r1.png','status':'planned','ownerApproved':False,'runtimeReady':False})
